package render

import (
	"fmt"
	"strings"
)

// renderPlain writes, per environment, a script that applies every app in
// reconciliation order. It is for people wiring the manifests into their own
// tooling, and for a first manual rollout.
func (r *renderer) renderPlain(l layout) error {
	for _, env := range l.envs {
		var b strings.Builder
		fmt.Fprintf(&b, `#!/usr/bin/env bash
# Generated by gitopsify. Applies the %[1]s environment in reconciliation
# order with server-side apply. Extra arguments go to kubectl, for example:
#   ./apply-%[1]s.sh --context %[1]s
set -euo pipefail
cd "$(dirname "$0")"

build() {
  if command -v kustomize >/dev/null 2>&1; then
    kustomize build "$@"
  else
    kubectl kustomize "$@"
  fi
}

apply() {
  local dir=$1
  shift
  echo ">> ${dir}"
  build "${dir}" | kubectl apply --server-side --field-manager=gitopsify --force-conflicts -f - "$@"
}

apply_helm() {
  local dir=$1
  shift
  echo ">> ${dir} (helm)"
  build --enable-helm "${dir}" | kubectl apply --server-side --field-manager=gitopsify --force-conflicts -f - "$@"
}
`, env.Name)
		wave := 0
		first := true
		for _, a := range r.appsByWave() {
			if first || a.Wave != wave {
				fmt.Fprintf(&b, "\n# wave %d\n", a.Wave)
				wave, first = a.Wave, false
			}
			fn := "apply"
			if a.IsHelm() {
				fn = "apply_helm"
			}
			fmt.Fprintf(&b, "%s %s \"$@\"\n", fn, l.appEnv(a.Name, env.Name))
			if a.Name == "crds" || a.Phase == "crds" {
				b.WriteString("kubectl wait --for=condition=Established crd --all --timeout=120s \"$@\"\n")
			}
		}
		r.tree.Add(l.file("apply-"+env.Name+".sh"), []byte(b.String()))
	}
	return nil
}
